parameters.jsCode:
const response = $input.first().json;
const content = response.choices[0].message.content;
let set;
try {
  set = JSON.parse(content);
} catch(e) {
  throw new Error('GPT yanıtı JSON parse edilemedi: ' + content);
}

const kullanici_id = $('Webhook - Öğren Talebi').first().json.body.kullanici_id;

return [{
  json: {
    ders: set.ders,
    konu: set.konu,
    summary: set.summary,
    cards: set.cards,
    quiz: set.quiz,
    kullanici_id: kullanici_id,
    olusturulma_tarihi: new Date().toISOString()
  }
}];

